<section class="card form-card"><div class="card-header d-flex justify-content-between"><h2 class="section-title mb-0">รายการรายงาน</h2><span class="text-muted small"><?php echo $counts["total"]; ?> รายการ</span></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th class="ps-4 py-3">รหัส</th><th>วันที่สร้าง</th><th>หัวข้องาน</th><th>แผนก</th><th>ประเภทปัญหา</th><th>สถานะ</th><th>ผู้สร้าง</th><th class="pe-4 text-end">การจัดการ</th></tr></thead><tbody><?php if (!$task_rows): ?><tr><td colspan="8" class="text-center text-muted py-4">ยังไม่มีข้อมูลงาน</td></tr><?php endif; ?><?php foreach ($task_rows as $task): ?><?php [$label,$class]=status_meta($task["status"]); ?><tr><td class="ps-4 fw-semibold">#T-<?php echo str_pad((string)$task["id"],5,"0",STR_PAD_LEFT); ?></td><td><?php echo thai_date_time($task["created_at"]); ?></td><td><?php echo htmlspecialchars($task["title"],ENT_QUOTES,"UTF-8"); ?></td><td><?php echo htmlspecialchars($task["department"],ENT_QUOTES,"UTF-8"); ?></td><td><?php echo htmlspecialchars($problem_category_options[$task["category"]] ?? $task["category"],ENT_QUOTES,"UTF-8"); ?></td><td><span class="badge rounded-pill <?php echo $class; ?>"><?php echo $label; ?></span></td><td><?php echo htmlspecialchars($task["created_by_name"],ENT_QUOTES,"UTF-8"); ?></td><td class="pe-4 text-end"><button class="btn btn-sm btn-outline-primary" type="button" data-bs-toggle="modal" data-bs-target="#taskModal<?php echo $task["id"]; ?>">ดูรายละเอียด</button> <a class="btn btn-sm btn-outline-secondary" href="?edit=<?php echo $task["id"]; ?>">แก้ไข</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php foreach ($task_rows as $task): ?><?php [$label,$class]=status_meta($task["status"]); ?><div class="modal fade" id="taskModal<?php echo $task["id"]; ?>" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">รายละเอียดงาน #T-<?php echo str_pad((string)$task["id"],5,"0",STR_PAD_LEFT); ?></h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><strong>หัวข้องาน:</strong> <?php echo htmlspecialchars($task["title"],ENT_QUOTES,"UTF-8"); ?></div><div class="col-md-3"><strong>แผนก:</strong> <?php echo htmlspecialchars($task["department"],ENT_QUOTES,"UTF-8"); ?></div><div class="col-md-3"><strong>สถานะ:</strong> <span class="badge <?php echo $class; ?>"><?php echo $label; ?></span></div><div class="col-md-6"><strong>ประเภทปัญหา:</strong> <?php echo htmlspecialchars($problem_category_options[$task["category"]] ?? $task["category"],ENT_QUOTES,"UTF-8"); ?></div><div class="col-md-6"><strong>สถานที่:</strong> <?php echo htmlspecialchars($task["location"],ENT_QUOTES,"UTF-8"); ?></div><div class="col-12"><strong>รายละเอียดปัญหา:</strong><div class="mt-1"><?php echo nl2br(htmlspecialchars($task["problem"],ENT_QUOTES,"UTF-8")); ?></div></div><div class="col-12"><strong>วิธีแก้ไข:</strong><div class="mt-1"><?php echo nl2br(htmlspecialchars($task["solution"],ENT_QUOTES,"UTF-8")); ?></div></div><div class="col-md-6"><strong>เวลาเริ่ม:</strong> <?php echo thai_date_time($task["start_time"]); ?></div><div class="col-md-6"><strong>เวลาสิ้นสุด:</strong> <?php echo thai_date_time($task["finish_time"]); ?></div><div class="col-12"><strong>หมายเหตุ:</strong> <?php echo nl2br(htmlspecialchars($task["remark"],ENT_QUOTES,"UTF-8")); ?></div><div class="col-md-6"><strong>ผู้สร้าง:</strong> <?php echo htmlspecialchars($task["created_by_name"],ENT_QUOTES,"UTF-8"); ?></div><div class="col-md-6"><strong>สร้างเมื่อ:</strong> <?php echo thai_date_time($task["created_at"]); ?></div><div class="col-md-6"><strong>อัปเดตเมื่อ:</strong> <?php echo thai_date_time($task["updated_at"]); ?></div></div></div><div class="modal-footer"><a class="btn btn-primary" href="?edit=<?php echo $task["id"]; ?>">Edit Task</a><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">ปิด</button></div></div></div></div><?php endforeach; ?>
